/* @autogenerated */
package net.civeira.phylax.common.security.impl.rbac;

import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.security.impl.ActorImpl;
import net.civeira.phylax.common.security.scope.FieldDescription;
import net.civeira.phylax.common.security.scope.Kind;
import net.civeira.phylax.common.security.scope.ResourceDescription;
import net.civeira.phylax.common.security.scope.ScopeDescription;

@DisplayName("Keycloak RBAC store placeholder")
class KeycloakUnitTest {

  @Test
  @DisplayName("Should be active only for the keycloak model")
  void shouldBeActiveOnlyForKeycloakModel() {
    assertTrue(new Keycloak("keycloak").isActive());
    assertFalse(new Keycloak("phylax").isActive());
  }

  @Test
  @DisplayName("Should accept registrations and return no grants")
  void shouldIgnoreRegistrationsAndReturnNoGrants() {
    Keycloak store = new Keycloak("keycloak");
    ResourceDescription resource = ResourceDescription.builder().name("tenant").build();

    assertDoesNotThrow(() -> {
      store.registerResourceAction(resource,
          ScopeDescription.builder().name("read").kind(Kind.values()[0]).build());
      store.registerResourceField(resource, FieldDescription.builder().name("name").build());
    });
    assertNull(store.checkRoleScopes(ActorImpl.builder().build()));
    assertNull(store.checkRoleProperties(ActorImpl.builder().build()));
  }
}
